# Lunar Konstruksi - Form / Work Technical Public Redesign
# Frontend only. Backend/admin CRUD are not modified.
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Phase([string]$Message) { Write-Host "[FORMWORK] $Message" -ForegroundColor Cyan }
function Fail([string]$Message) { Write-Host ""; Write-Host "[FORMWORK] GAGAL: $Message" -ForegroundColor Red; exit 1 }
function Ensure-Parent([string]$Path) { $parent = Split-Path -Parent $Path; if ($parent -and -not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Force -Path $parent | Out-Null } }
function Write-Utf8([string]$Path,[string]$Content) { Ensure-Parent $Path; $enc=New-Object System.Text.UTF8Encoding($false); [System.IO.File]::WriteAllText($Path,$Content,$enc) }
function Decode([string]$Value) { [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value)) }

$repoRoot = (& git rev-parse --show-toplevel 2>$null)
if (-not $repoRoot) { Fail "Jalankan dari repository Git Lunar Konstruksi." }
$repoRoot=$repoRoot.Trim(); Set-Location $repoRoot
$branch=(& git branch --show-current).Trim(); $head=(& git rev-parse --short HEAD).Trim()
Phase "Repo   : $repoRoot"; Phase "Branch : $branch"; Phase "HEAD   : $head"

foreach ($required in @("package.json","components/site")) { if (-not (Test-Path -LiteralPath $required)) { Fail "Prasyarat tidak ditemukan: $required" } }

$mode = ""
if (Test-Path -LiteralPath "modules/public-site/server.ts") { $mode="modules" }
elseif (Test-Path -LiteralPath "features/public-site/server.ts") { $mode="features" }
elseif (Test-Path -LiteralPath "components/site/use-public-overview.ts") { $mode="classic" }
else { Fail "Data publik tidak terdeteksi. Diperlukan modules/public-site, features/public-site, atau use-public-overview.ts." }
Phase "Data mode: $mode"

$stamp=Get-Date -Format "yyyyMMdd-HHmmss"
$backup=Join-Path $repoRoot ".lunar-backups/formwork-redesign-$stamp"
New-Item -ItemType Directory -Force -Path $backup | Out-Null
$targets=@(
  "components/site/home-page.tsx","components/site/about-page.tsx","components/site/services-page.tsx",
  "components/site/projects-page.tsx","components/site/contact-page.tsx","components/site/site-header.tsx","components/site/site-footer.tsx",
  "components/site/formwork"
)
foreach($target in $targets){ if(Test-Path -LiteralPath $target){ $dest=Join-Path $backup $target; Ensure-Parent $dest; Copy-Item -LiteralPath $target -Destination $dest -Recurse -Force } }
Phase "Backup frontend: $backup"

$common=@{}
$common["FORMWORK_PUBLIC_DESIGN.md"]=""
$common["components/site/formwork/about.tsx"]=""
$common["components/site/formwork/contact-form.tsx"]=""
$common["components/site/formwork/contact.tsx"]=""
$common["components/site/formwork/data.ts"]=""
$common["components/site/formwork/decor.tsx"]=""
$common["components/site/formwork/footer.tsx"]=""
$common["components/site/formwork/header.tsx"]=""
$common["components/site/formwork/home.tsx"]=""
$common["components/site/formwork/media.tsx"]=""
$common["components/site/formwork/projects.tsx"]=""
$common["components/site/formwork/services.tsx"]=""
$common["components/site/site-footer.tsx"]="aW1wb3J0IHsgRm9ybXdvcmtGb290ZXIgfSBmcm9tICIuL2Zvcm13b3JrL2Zvb3RlciI7CgpleHBvcnQgZnVuY3Rpb24gU2l0ZUZvb3RlcigpIHsKICByZXR1cm4gPEZvcm13b3JrRm9vdGVyIC8+Owp9CgpleHBvcnQgZGVmYXVsdCBTaXRlRm9vdGVyOwo="
$common["components/site/site-header.tsx"]="InVzZSBjbGllbnQiOwoKaW1wb3J0IHsgRm9ybXdvcmtIZWFkZXIgfSBmcm9tICIuL2Zvcm13b3JrL2hlYWRlciI7CgpleHBvcnQgZnVuY3Rpb24gU2l0ZUhlYWRlcigpIHsKICByZXR1cm4gPEZvcm13b3JrSGVhZGVyIC8+Owp9CgpleHBvcnQgZGVmYXVsdCBTaXRlSGVhZGVyOwo="

$variants=@{}
$variants["modules:about-page.tsx"]=""
$variants["modules:contact-page.tsx"]=""
$variants["modules:home-page.tsx"]=""
$variants["modules:projects-page.tsx"]=""
$variants["modules:services-page.tsx"]=""
$variants["features:about-page.tsx"]=""
$variants["features:contact-page.tsx"]=""
$variants["features:home-page.tsx"]=""
$variants["features:projects-page.tsx"]=""
$variants["features:services-page.tsx"]=""
$variants["classic:about-page.tsx"]=""
$variants["classic:contact-page.tsx"]=""
$variants["classic:home-page.tsx"]=""
$variants["classic:projects-page.tsx"]=""
$variants["classic:services-page.tsx"]=""

foreach($entry in $common.GetEnumerator()){
  $target=Join-Path $repoRoot $entry.Key
  Write-Utf8 $target (Decode $entry.Value)
  Write-Host "[FORMWORK] write  $($entry.Key)" -ForegroundColor DarkGray
}

$pageMap=@{
  "home-page.tsx"="components/site/home-page.tsx";
  "about-page.tsx"="components/site/about-page.tsx";
  "services-page.tsx"="components/site/services-page.tsx";
  "projects-page.tsx"="components/site/projects-page.tsx";
  "contact-page.tsx"="components/site/contact-page.tsx"
}
foreach($name in $pageMap.Keys){
  $key="$mode`:$name"
  if(-not $variants.ContainsKey($key)){ Fail "Variant wrapper tidak ditemukan: $key" }
  Write-Utf8 (Join-Path $repoRoot $pageMap[$name]) (Decode $variants[$key])
  Write-Host "[FORMWORK] write  $($pageMap[$name]) [$mode]" -ForegroundColor DarkGray
}

Write-Host ""
Write-Host "[FORMWORK] Redesign frontend selesai diterapkan." -ForegroundColor Green
Write-Host "[FORMWORK] Backend/admin CRUD tidak diubah." -ForegroundColor Green
Write-Host "[FORMWORK] Tidak ada dependency baru; npm install tidak diperlukan." -ForegroundColor Green
Write-Host ""
Write-Host "Validasi:" -ForegroundColor Cyan
Write-Host "  npm run lint"
Write-Host "  npm run typecheck"
Write-Host "  npm run build"
Write-Host "  git diff --check"
Write-Host "  npm run dev"
